input.content:
// PriorProof engine contract.
//
// This file is the shared contract every other module compiles against. It is
// pure types: no runtime, no `next/*`, no `process.env`. The engine is an async
// generator that yields EngineEvent values as it works, so the API route can
// stream them and the UI can fill the coverage matrix live.
//
// The one invariant the whole product rests on: a criterion is `proven` only when
// a real span in the chart supports it and both independent passes agree on that
// span. Anything the chart cannot support is a `gap`, never a hopeful green.

/** A single medical-necessity criterion parsed from the payer policy. */
export interface Criterion {
  /** Stable id, e.g. "C1", "C4c". */
  id: string;
  /** The exact policy wording for this criterion. */
  text: string;
  /** Optional group label, e.g. "Conservative therapy". */
  group?: string;
  /** Where in the policy this came from (section or footnote). */
  policySource: string;
  /** Rough type tag for display and validation, e.g. "imaging", "step-therapy". */
  kind?: string;
}

/** Prove-or-refuse. There is deliberately no third "approved" verdict. */
export type Verdict = "proven" | "gap";

/** A cited span in the chart, so a green row always points at real text. */
export interface ChartSpan {
  /** The exact chart text quoted. */
  quote: string;
  /** Optional section the quote came from, e.g. "IMAGING". */
  section?: string;
  /** Optional character offset of the quote in the chart, for highlighting. */
  offset?: number;
}

/** One independent pass over the chart for one criterion. */
export interface EvidencePass {
  pass: 1 | 2;
  found: boolean;
  /** The span this pass believes supports the criterion, if any. */
  cite?: ChartSpan;
  /** Why this pass concluded found or not-found. */
  reasoning: string;
}

/** The resolved decision for one criterion. */
export interface CriterionResult {
  criterion: Criterion;
  verdict: Verdict;
  /** Both independent passes, kept for the audit trail. */
  passes: EvidencePass[];
  /** Present if and only if proven: the span both passes agreed on. */
  cite?: ChartSpan;
  /** Present if and only if gap: what is missing and the one line that fixes it. */
  gapReason?: string;
  rationale: string;
}

/** A pointer to the public policy the criteria came from. */
export interface PolicyRef {
  name: string;
  payer: string;
  url: string;
  retrieved?: string;
}

/** The submission-ready packet the agent assembles. */
export interface Packet {
  caseId: string;
  service: string;
  policy: PolicyRef;
  results: CriterionResult[];
  provenCount: number;
  gapCount: number;
  /** "action-needed" whenever any criterion is a gap. */
  decision: "ready" | "action-needed";
  coverLetter: string;
}

/** The input case: a policy decomposed into criteria plus the chart text. */
export interface CaseInput {
  caseId: string;
  service: string;
  policy: PolicyRef;
  criteria: Criterion[];
  chart: string;
}

/** Expected labels for the validation and test oracle, per fixture. */
export interface CaseExpectation {
  caseId: string;
  expected: Record<
    string,
    { verdict: Verdict; citeContains?: string; gapContains?: string }
  >;
}

/** Streaming events the engine yields, consumed by the SSE route and the UI. */
export type EngineEvent =
  | { type: "run_start"; caseId: string; service: string; policy: PolicyRef }
  | { type: "criteria_parsed"; criteria: Criterion[] }
  | { type: "criterion_start"; id: string }
  | {
      type: "evidence";
      id: string;
      pass: 1 | 2;
      found: boolean;
      cite?: ChartSpan;
      reasoning: string;
    }
  | { type: "criterion_resolved"; result: CriterionResult }
  | { type: "packet_ready"; packet: Packet }
  | { type: "run_error"; message: string };

/** The LLM client the engine depends on. Injected, so the engine never reads env. */
export interface LlmClient {
  readonly provider: string;
  readonly model: string;
  complete(args: {
    system: string;
    prompt: string;
    json?: boolean;
    maxTokens?: number;
    signal?: AbortSignal;
  }): Promise<string>;
}

/** The trace sink the engine writes spans to (neatlogs plus a local store). Injected. */
export interface TraceSink {
  span<T>(
    name: string,
    kind: string,
    attrs: Record<string, unknown>,
    fn: (set: (k: string, v: unknown) => void) => Promise<T>,
  ): Promise<T>;
  event(name: string, attrs: Record<string, unknown>): void;
}

/** Dependencies injected into the engine run. */
export interface EngineDeps {
  llm: LlmClient;
  trace?: TraceSink;
  /** Cap criteria for a bounded demo run. */
  maxCriteria?: number;
}

// Aetna CPB 0743 lumbar laminotomy / microdiscectomy demo case.
//
// Policy criteria are quoted verbatim from the public bulletin (whitespace only
// normalised). Verify against the live policy before a submission run, since a
// payer can revise the wording:
//   https://www.aetna.com/cpb/medical/data/700_799/0743.html
//
// The chart satisfies eight of nine criteria. The one gap is C4c: the policy
// requires active in-person physical therapy for the full duration confirmed by
// PT notes or claims, and the chart documents only a self-directed home routine.

import type {
  CaseInput,
  CaseExpectation,
  Criterion,
  PolicyRef,
} from "@/lib/engine/types";
import { aetna0743Chart } from "./aetna-0743-chart";

const policy: PolicyRef = {
  name: "Aetna CPB 0743: Spinal Surgery (Laminectomy and Fusion), lumbar laminectomy for a herniated disc",
  payer: "Aetna",
  url: "https://www.aetna.com/cpb/medical/data/700_799/0743.html",
  retrieved: "2026-10-10",
};

const criteria: Criterion[] = [
  {
    id: "C1",
    group: "Primary",
    kind: "ruling-out",
    policySource: "CPB 0743, criterion 1",
    text: "All other reasonable sources of pain and/or neurological deficit have been ruled out, including but not limited to significant pathology at other spinal level(s) on the advanced imaging radiology report that is/are not part of the surgical request resulting in incomplete surgical planning",
  },
  {
    id: "C2",
    group: "Primary",
    kind: "clinical-findings",
    policySource: "CPB 0743, criterion 2",
    text: "Member has signs or symptoms of neural compression (radiculopathy, neurogenic extremity claudication, myelopathy) associated with the levels being treated",
  },
  {
    id: "C3",
    group: "Primary",
    kind: "imaging",
    policySource: "CPB 0743, criterion 3",
    text: "Advanced imaging studies (CT or MRI) indicate central/lateral recess or foraminal stenosis (graded as moderate, moderate to severe or severe; not mild or mild to moderate), or nerve root or spinal cord compression, at the level corresponding with the clinical findings",
  },
  {
    id: "C4a",
    group: "Conservative therapy",
    kind: "duration",
    policySource: "CPB 0743, criterion 4 + Footnote 1",
    text: "Member has failed at least 6 weeks of conservative therapy",
  },
  {
    id: "C4b",
    group: "Conservative therapy",
    kind: "recency",
    policySource: "CPB 0743, Footnote 1",
    text: "Conservative measures were recent (within the past year)",
  },
  {
    id: "C4c",
    group: "Conservative therapy",
    kind: "step-therapy",
    policySource: "CPB 0743, Footnote 1",
    text: "Active in-person physical therapy (not home or virtual) for the entire required duration, confirmed by the actual PT notes or by documentation in the member claims history",
  },
  {
    id: "C4d",
    group: "Conservative therapy",
    kind: "medication",
    policySource: "CPB 0743, Footnote 1",
    text: "Trial of medications (NSAIDs, acetaminophen, or tricyclic antidepressants)",
  },
  {
    id: "C4e",
    group: "Conservative therapy",
    kind: "education",
    policySource: "CPB 0743, Footnote 1",
    text: "Patient education provided",
  },
  {
    id: "C5",
    group: "Primary",
    kind: "function",
    policySource: "CPB 0743, criterion 5",
    text: "Member's activities of daily living are limited by symptoms of neural compression",
  },
];

export const aetna0743Case: CaseInput = {
  caseId: "aetna-0743-lumbar",
  service: "Right L5-S1 lumbar laminotomy with microdiscectomy (CPT 63030)",
  policy,
  criteria,
  chart: aetna0743Chart,
};

export const aetna0743Expectation: CaseExpectation = {
  caseId: "aetna-0743-lumbar",
  expected: {
    C1: { verdict: "proven", citeContains: "isolated to the right\nL5-S1 level" },
    C2: { verdict: "proven", citeContains: "positive right straight-leg raise" },
    C3: { verdict: "proven", citeContains: "moderate-to-severe right lateral recess narrowing" },
    C4a: { verdict: "proven", citeContains: "past 10 weeks" },
    C4b: { verdict: "proven", citeContains: "July to September 2026" },
    C4c: { verdict: "gap", gapContains: "in-person physical therapy" },
    C4d: { verdict: "proven", citeContains: "naproxen 500 mg" },
    C4e: { verdict: "proven", citeContains: "written lumbar self-care education" },
    C5: { verdict: "proven", citeContains: "unable to work his delivery-driver shifts" },
  },
};

// Fixture loader. The policy + synthetic chart cases live under ./cases.
// Everything here is public policy text plus synthetic (no-PHI) charts.

import type { CaseInput, CaseExpectation } from "@/lib/engine/types";
import { aetna0743Case, aetna0743Expectation } from "./cases/aetna-0743-lumbar";

export interface CaseEntry {
  input: CaseInput;
  expectation: CaseExpectation;
}

const CASES: Record<string, CaseEntry> = {
  [aetna0743Case.caseId]: {
    input: aetna0743Case,
    expectation: aetna0743Expectation,
  },
};

export const DEFAULT_CASE_ID = aetna0743Case.caseId;

export function listCases(): {
  caseId: string;
  service: string;
  policy: string;
  criteriaCount: number;
}[] {
  return Object.values(CASES).map((c) => ({
    caseId: c.input.caseId,
    service: c.input.service,
    policy: c.input.policy.name,
    criteriaCount: c.input.criteria.length,
  }));
}

export function loadCase(caseId: string): CaseInput {
  const entry = CASES[caseId];
  if (!entry) throw new Error(`unknown case: ${caseId}`);
  return entry.input;
}

export function loadExpectation(caseId: string): CaseExpectation {
  const entry = CASES[caseId];
  if (!entry) throw new Error(`unknown case: ${caseId}`);
  return entry.expectation;
}

// Engine entry point. STUB: replaced by the engine build.
// Re-exports the contract so consumers can import from "@/lib/engine".
export * from "./types";
import type { CaseInput, EngineDeps, EngineEvent } from "./types";

// The real engine parses the policy into criteria, runs two independent evidence
// passes per criterion, and yields events as each resolves. This stub keeps the
// type contract so the UI and route compile while the engine build fills it in.
// It yields a loud error rather than a silent pass.
export async function* runEngine(
  input: CaseInput,
  deps: EngineDeps,
): AsyncGenerator<EngineEvent> {
  void input;
  void deps;
  yield { type: "run_error", message: "engine not implemented (stub)" };
}

// Provider-agnostic LLM client. STUB: replaced by the LLM build.
// Reads server-only env (OPENAI_API_KEY, optional ANTHROPIC_API_KEY), never a
// NEXT_PUBLIC var, and is only ever imported from server code.
import type { LlmClient } from "@/lib/engine/types";

export function getLlmClient(): LlmClient {
  return {
    provider: "stub",
    model: "stub",
    async complete() {
      throw new Error("llm client not implemented (stub)");
    },
  };
}

// Trace sink. STUB: replaced by the trace build with a neatlogs dual-write.
// The real version emits spans to neatlogs when NEATLOGS_API_KEY is set and
// ALWAYS also records them to a local store so the UI renders the trace live
// with or without a key. This stub is a working no-op so the engine runs.
import type { TraceSink } from "@/lib/engine/types";

export interface TraceController {
  sink: TraceSink;
  flush(): Promise<void>;
  snapshot(): { spans: unknown[] };
}

export function createTrace(opts?: { runId?: string; caseId?: string }): TraceController {
  void opts;
  const sink: TraceSink = {
    async span(name, kind, attrs, fn) {
      void name;
      void kind;
      void attrs;
      return fn(() => {});
    },
    event() {},
  };
  return {
    sink,
    async flush() {},
    snapshot() {
      return { spans: [] };
    },
  };
}

import { defineConfig } from "vitest/config";
import { fileURLToPath } from "node:url";
import { dirname } from "node:path";

const root = dirname(fileURLToPath(import.meta.url));

export default defineConfig({
  test: {
    include: ["__tests__/**/*.test.ts", "lib/**/*.test.ts"],
    environment: "node",
  },
  resolve: {
    alias: { "@": root },
  },
});

