{
  "_comment": "Reviewed, accepted high/critical npm advisories. verify.sh fails on any high/critical with a fix that is NOT listed here. Each entry is a deliberate exception with a reason, re-evaluated when the upstream situation changes. See SECURITY.md.",
  "accept": [
    {
      "module": "@opentelemetry/propagator-jaeger",
      "id": "GHSA-45rx-2jwx-cxfr",
      "reason": "Denial of service in JaegerPropagator.extract via a malformed header. The fix is >=2.9.0, which pulls the OpenTelemetry 2.x core. The mandatory neatlogs 1.1.26 package is pinned to the OpenTelemetry 1.x stack (sdk-trace-node 1.30.1), and forcing core 2.x removes exports neatlogs needs (hexToBinary, getEnvWithoutDefaults) and breaks the build. PriorProof never configures or uses the Jaeger propagator, so no untrusted header reaches it. Re-evaluate when neatlogs ships an OpenTelemetry 2.x build."
    },
    {
      "module": "braces",
      "id": "GHSA-vfj7-8cjw-p6xm",
      "reason": "Stack-exhaustion denial of service in braces <=3.0.3, with no upstream fix available. Dev-only: it reaches the tree solely through eslint-config-next -> @next/eslint-plugin-next -> fast-glob -> micromatch -> braces, so it is never bundled into the deployed app and only runs on trusted lint input during development."
    }
  ]
}

input.old_string:
step "supply chain: audit (fail only on a high or critical advisory that has a fix)"
# pnpm audit exits non-zero whenever it finds anything at the audit level, so
# capture it instead of letting set -e stop here. The verdict is decided from the
# JSON: a high or critical advisory with a fix fails the gate, the rest are printed.
audit_json="$(pnpm audit --audit-level=high --json 2>/dev/null || true)"
printf '%s' "$audit_json" | node -e '
let raw = "";
process.stdin.on("data", (d) => (raw += d));
process.stdin.on("end", () => {
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    console.log("audit output was not valid JSON (registry error or no network). Not failing the gate.");
    process.exit(0);
  }
  const rows = [];
  // npm v6 / pnpm classic shape: { advisories: { id: {...} } }
  if (data.advisories && typeof data.advisories === "object") {
    for (const a of Object.values(data.advisories)) {
      const patched = typeof a.patched_versions === "string" ? a.patched_versions : "";
      const fix =
        typeof a.fixAvailable !== "undefined"
          ? Boolean(a.fixAvailable)
          : patched !== "" && patched !== "<0.0.0";
      rows.push({
        name: a.module_name || a.name || "(unknown)",
        severity: String(a.severity || "unknown").toLowerCase(),
        fix,
        title: a.title || "",
        url: a.url || "",
      });
    }
  }
  // npm v7+ shape: { vulnerabilities: { name: {...} } }
  if (!data.advisories && data.vulnerabilities && typeof data.vulnerabilities === "object") {
    for (const [name, v] of Object.entries(data.vulnerabilities)) {
      const via = Array.isArray(v.via)
        ? v.via.map((x) => (x && x.title) || "").filter(Boolean).join("; ")
        : "";
      rows.push({
        name,
        severity: String(v.severity || "unknown").toLowerCase(),
        fix: Boolean(v.fixAvailable),
        title: via,
        url: "",
      });
    }
  }
  const highcrit = rows.filter((r) => r.severity === "high" || r.severity === "critical");
  if (highcrit.length === 0) {
    console.log("no high or critical advisories.");
    process.exit(0);
  }
  for (const r of highcrit) {
    console.log(
      "  " + r.severity.toUpperCase() + " " + r.name + " fix=" + (r.fix ? "available" : "none") +
        (r.title ? " :: " + r.title : "") +
        (r.url ? " " + r.url : ""),
    );
  }
  const fixable = highcrit.filter((r) => r.fix);
  if (fixable.length > 0) {
    console.log("\n" + fixable.length + " high/critical advisory(ies) have a fix. Run pnpm update and re-run the gate.");
    process.exit(1);
  }
  console.log("\n" + highcrit.length + " high/critical advisory(ies) with no fix available. Printed, not failing the gate.");
  process.exit(0);
});
'

