1	// OpenAI adapter for the engine's LlmClient contract. Server-only.
2	//
3	// The API key is read in client.ts and passed in here, never from this module
4	// and never from a NEXT_PUBLIC var. This file holds no secret of its own and
5	// logs nothing. On any failure it surfaces a short message with the provider
6	// and the HTTP status, never the key or the raw request.
7	import OpenAI from "openai";
8	import type { LlmClient } from "@/lib/engine/types";
9	
10	const DEFAULT_MODEL = "gpt-4o-mini";
11	const TIMEOUT_MS = 30_000;
12	
13	/** Thrown by withTimeout when our own deadline fires, so the catch can tell a
14	 * timeout apart from a caller cancel or a real API error. */
15	class TimeoutError extends Error {}
16	
17	/**
18	 * Run `fn` with a signal that aborts on either the caller's signal or a local
19	 * deadline, whichever comes first. The timer is always cleared and the caller
20	 * listener always removed, so no handle leaks on success or failure.
21	 */
22	async function withTimeout<T>(
23	  signal: AbortSignal | undefined,
24	  timeoutMs: number,
25	  fn: (merged: AbortSignal) => Promise<T>,
26	): Promise<T> {
27	  const controller = new AbortController();
28	  let timedOut = false;
29	  const onAbort = () => controller.abort();
30	  if (signal) {
31	    if (signal.aborted) controller.abort();
32	    else signal.addEventListener("abort", onAbort, { once: true });
33	  }
34	  const timer: ReturnType<typeof setTimeout> = setTimeout(() => {
35	    timedOut = true;
36	    controller.abort();
37	  }, timeoutMs);
38	  try {
39	    return await fn(controller.signal);
40	  } catch (err) {
41	    if (timedOut) throw new TimeoutError();
42	    throw err;
43	  } finally {
44	    clearTimeout(timer);
45	    signal?.removeEventListener("abort", onAbort);
46	  }
47	}
48	
49	/** Turn any thrown value into a clean Error that carries no secret. */
50	function cleanError(err: unknown, callerSignal: AbortSignal | undefined): Error {
51	  if (err instanceof TimeoutError) {
52	    return new Error(`openai request timed out after ${TIMEOUT_MS}ms`);
53	  }
54	  if (callerSignal?.aborted) {
55	    return err instanceof Error ? err : new Error("openai request aborted");
56	  }
57	  const status = (err as { status?: unknown })?.status;
58	  if (typeof status === "number") {
59	    return new Error(`openai API error (status ${status})`);
60	  }
61	  const detail = err instanceof Error ? err.message : "unknown error";
62	  return new Error(`openai API error: ${detail}`);
63	}
64	
65	/** Build an LlmClient backed by the OpenAI chat completions API. */
66	export function createOpenAiClient(apiKey: string): LlmClient {
67	  const model = process.env.OPENAI_MODEL || DEFAULT_MODEL;
68	  const client = new OpenAI({ apiKey });
69	
70	  return {
71	    provider: "openai",
72	    model,
73	    async complete(args) {
74	      // json_object mode requires the word JSON in the input, so name it in the
75	      // system message. This also keeps the instruction visible to the model.
76	      const system = args.json
77	        ? `${args.system}\n\nRespond with a single valid JSON object and nothing else.`
78	        : args.system;
79	
80	      let completion;
81	      try {
82	        completion = await withTimeout(args.signal, TIMEOUT_MS, (merged) =>
83	          client.chat.completions.create(
84	            {
85	              model,
86	              messages: [
87	                { role: "system", content: system },
88	                { role: "user", content: args.prompt },
89	              ],
90	              max_completion_tokens: args.maxTokens,
91	              response_format: args.json
92	                ? { type: "json_object" as const }
93	                : undefined,
94	            },
95	            { signal: merged },
96	          ),
97	        );
98	      } catch (err) {
99	        throw cleanError(err, args.signal);
100	      }
101	
102	      const content = completion.choices[0]?.message?.content;
103	      if (content == null) {
104	        throw new Error("openai returned an empty response");
105	      }
106	      return content;
107	    },
108	  };
109	}
