1	// One independent evidence pass for one criterion.
2	//
3	// The pass asks the injected LLM whether the chart supports this exact criterion
4	// and, if so, for a single verbatim quote from the chart. The model is never
5	// trusted: the returned quote is validated against the chart before found stays
6	// true. A quote that is not present verbatim (whitespace-collapsed matching is
7	// allowed) forces found=false, so a fabricated citation can never go green.
8	
9	import type { ChartSpan, Criterion, EvidencePass, LlmClient } from "./types";
10	
11	const SYSTEM_PASS_1 =
12	  "You are a prior-authorization reviewer. You read one payer policy criterion plus a patient chart, then decide whether the chart gives direct support for that single criterion. You never invent support. When the chart does not clearly support it you answer not found.";
13	
14	const SYSTEM_PASS_2 =
15	  "You are a second independent clinical auditor. Working only from the patient chart, you decide whether the record by itself proves this one policy requirement. You do not assume facts the chart does not state. When the proof is absent you answer not found.";
16	
17	/** Build the per-pass prompt. The pass number and criterion id are included so a
18	 *  deterministic test client can answer without a network call. */
19	function buildEvidencePrompt(
20	  criterion: Criterion,
21	  chart: string,
22	  pass: 1 | 2,
23	): string {
24	  return [
25	    `Independent pass ${pass} of 2.`,
26	    `Decide if the chart below supports this one criterion.`,
27	    `Criterion [${criterion.id}]: ${criterion.text}`,
28	    ``,
29	    `CHART:`,
30	    `<<<`,
31	    chart,
32	    `>>>`,
33	    ``,
34	    `Return only JSON of the form {"found": true, "quote": "<one span copied verbatim from the chart>", "reasoning": "<one or two sentences>"}.`,
35	    `Copy the quote exactly from the chart. Do not paraphrase. When nothing in the chart supports the criterion, set found to false with an empty quote.`,
36	  ].join("\n");
37	}
38	
39	/** Collapse every run of whitespace to a single space, then trim. */
40	export function collapseWs(value: string): string {
41	  return value.replace(/\s+/g, " ").trim();
42	}
43	
44	/** Parse a model response into a value without ever throwing. Tolerates code
45	 *  fences and leading or trailing prose by extracting the first JSON object or
46	 *  array it can find. Returns null when nothing parses. */
47	export function safeJson(raw: unknown): unknown {
48	  if (typeof raw !== "string") return null;
49	  let text = raw.trim();
50	  if (text.length === 0) return null;
51	  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
52	  if (fence && typeof fence[1] === "string") text = fence[1].trim();
53	  const direct = tryParse(text);
54	  if (direct !== undefined) return direct;
55	  const firstObj = text.indexOf("{");
56	  const lastObj = text.lastIndexOf("}");
57	  if (firstObj >= 0 && lastObj > firstObj) {
58	    const obj = tryParse(text.slice(firstObj, lastObj + 1));
59	    if (obj !== undefined) return obj;
60	  }
61	  const firstArr = text.indexOf("[");
62	  const lastArr = text.lastIndexOf("]");
63	  if (firstArr >= 0 && lastArr > firstArr) {
64	    const arr = tryParse(text.slice(firstArr, lastArr + 1));
65	    if (arr !== undefined) return arr;
66	  }
67	  return null;
68	}
69	
70	function tryParse(text: string): unknown {
71	  try {
72	    return JSON.parse(text);
73	  } catch {
74	    return undefined;
75	  }
76	}
77	
78	function asRecord(value: unknown): Record<string, unknown> {
79	  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
80	    return value as Record<string, unknown>;
81	  }
82	  return {};
83	}
84	
85	function readBool(rec: Record<string, unknown>, key: string): boolean | undefined {
86	  const x = rec[key];
87	  return typeof x === "boolean" ? x : undefined;
88	}
89	
90	function readString(rec: Record<string, unknown>, key: string): string | undefined {
91	  const x = rec[key];
92	  return typeof x === "string" ? x : undefined;
93	}
94	
95	/** Build the whitespace-collapsed form of the chart plus an index map back to the
96	 *  original string. map[i] is the original index of collapsed character i. Each
97	 *  run of whitespace collapses to one space mapped to the run's first character. */
98	function collapseWithMap(chart: string): { norm: string; map: number[] } {
99	  let norm = "";
100	  const map: number[] = [];
101	  const n = chart.length;
102	  let i = 0;
103	  while (i < n) {
104	    const ch = chart.charAt(i);
105	    if (/\s/.test(ch)) {
106	      const runStart = i;
107	      while (i < n && /\s/.test(chart.charAt(i))) i++;
108	      norm += " ";
109	      map.push(runStart);
110	    } else {
111	      norm += ch;
112	      map.push(i);
113	      i++;
114	    }
115	  }
116	  return { norm, map };
117	}
118	
119	/** Confirm a quote is really in the chart and return the verbatim chart span.
120	 *  First tries a plain substring. If that fails it tries a whitespace-collapsed
121	 *  match, then maps the match back to the exact chart slice so the returned
122	 *  quote is always a verbatim substring of the chart. Returns null when the
123	 *  quote is not present, which is how a hallucinated citation is rejected. */
124	export function findVerbatimSpan(chart: string, rawQuote: unknown): ChartSpan | null {
125	  if (typeof rawQuote !== "string") return null;
126	  const quote = rawQuote.trim();
127	  if (quote.length === 0) return null;
128	
129	  const direct = chart.indexOf(quote);
130	  if (direct >= 0) return { quote, offset: direct };
131	
132	  const needle = collapseWs(quote);
133	  if (needle.length === 0) return null;
134	  const { norm, map } = collapseWithMap(chart);
135	  const at = norm.indexOf(needle);
136	  if (at < 0) return null;
137	  const start = map[at];
138	  const lastNormIdx = at + needle.length - 1;
139	  const lastOrig = map[lastNormIdx];
140	  if (typeof start !== "number" || typeof lastOrig !== "number") return null;
141	  const end = lastOrig + 1;
142	  const slice = chart.slice(start, end);
143	  if (slice.length === 0 || chart.indexOf(slice) < 0) return null;
144	  return { quote: slice, offset: start };
145	}
146	
147	/** Best-effort section header for a cited span. Scans backward for the nearest
148	 *  all-caps heading line. Optional and never throws. */
149	function sectionFor(chart: string, offset: number | undefined): string | undefined {
150	  if (typeof offset !== "number" || offset < 0) return undefined;
151	  const before = chart.slice(0, offset);
152	  const lines = before.split("\n");
153	  for (let i = lines.length - 1; i >= 0; i--) {
154	    const line = (lines[i] ?? "").trim();
155	    if (line.length >= 3 && /^[A-Z][A-Z /&-]+$/.test(line)) return line;
156	  }
157	  return undefined;
158	}
159	
160	/** Run one independent evidence pass. Asks the LLM, then validates the quote
161	 *  against the chart. A quote that is not a verbatim chart span forces
162	 *  found=false so a fabricated citation never counts as support. */
163	export async function findEvidence(
164	  criterion: Criterion,
165	  chart: string,
166	  llm: LlmClient,
167	  pass: 1 | 2,
168	): Promise<EvidencePass> {
169	  const system = pass === 1 ? SYSTEM_PASS_1 : SYSTEM_PASS_2;
170	  const prompt = buildEvidencePrompt(criterion, chart, pass);
171	  const raw = await llm.complete({ system, prompt, json: true, maxTokens: 700 });
172	
173	  const rec = asRecord(safeJson(raw));
174	  const claimedFound = readBool(rec, "found") ?? readBool(rec, "supported") ?? false;
175	  const quoteRaw = readString(rec, "quote");
176	  const reasoning = readString(rec, "reasoning") ?? "";
177	
178	  if (!claimedFound || quoteRaw === undefined || quoteRaw.trim().length === 0) {
179	    return {
180	      pass,
181	      found: false,
182	      reasoning: reasoning || `Pass ${pass} found no supporting span in the chart.`,
183	    };
184	  }
185	
186	  const span = findVerbatimSpan(chart, quoteRaw);
187	  if (!span) {
188	    return {
189	      pass,
190	      found: false,
191	      reasoning: `Pass ${pass} rejected a quote that is not present verbatim in the chart. Treated as not found.`,
192	    };
193	  }
194	
195	  const section = sectionFor(chart, span.offset);
196	  const cite: ChartSpan = section ? { ...span, section } : span;
197	  return {
198	    pass,
199	    found: true,
200	    cite,
201	    reasoning: reasoning || `Pass ${pass} cited a verbatim chart span supporting ${criterion.id}.`,
202	  };
203	}
204

